&lt;svg width="100%" viewBox="0 0 720 400" xmlns="http://www.w3.org/2000/svg" style="max-width: 100%; height: auto;"&gt;
  &lt;!-- Title --&gt;
  &lt;text x="360" y="30" font-size="18" font-weight="500" text-anchor="middle" fill="#2c3e50"&gt;States with Significant Mineral Rights Activity&lt;/text&gt;

  &lt;!-- Legend --&gt;
  &lt;rect x="100" y="50" width="520" height="80" fill="#f9f9f9" stroke="#ddd" stroke-width="1" rx="4"/&gt;

  &lt;rect x="110" y="60" width="14" height="14" fill="#e74c3c" opacity="0.9"/&gt;
  &lt;text x="135" y="70" font-size="11" fill="#333"&gt;High Risk: Active oil/gas operations, frequent surface disturbance&lt;/text&gt;

  &lt;rect x="110" y="85" width="14" height="14" fill="#e67e22" opacity="0.8"/&gt;
  &lt;text x="135" y="95" font-size="11" fill="#333"&gt;Medium Risk: Historical operations, dormant leases, title uncertainty&lt;/text&gt;

  &lt;rect x="110" y="110" width="14" height="14" fill="#27ae60" opacity="0.7"/&gt;
  &lt;text x="135" y="120" font-size="11" fill="#333"&gt;Low Risk: Minimal mineral activity or clear surface use agreements&lt;/text&gt;

  &lt;!-- State listing --&gt;
  &lt;text x="100" y="170" font-size="12" font-weight="500" fill="#2c3e50"&gt;HIGH RISK STATES:&lt;/text&gt;
  &lt;text x="120" y="190" font-size="11" fill="#333"&gt;Texas, Oklahoma, Louisiana, Wyoming, Colorado, New Mexico, Montana&lt;/text&gt;
  &lt;text x="120" y="210" font-size="11" fill="#333"&gt;Utah, Kansas, North Dakota, Pennsylvania (natural gas)&lt;/text&gt;

  &lt;text x="100" y="245" font-size="12" font-weight="500" fill="#2c3e50"&gt;MEDIUM RISK STATES:&lt;/text&gt;
  &lt;text x="120" y="265" font-size="11" fill="#333"&gt;California, Nevada, Arizona, Nebraska, South Dakota, Alaska&lt;/text&gt;

  &lt;text x="100" y="300" font-size="12" font-weight="500" fill="#2c3e50"&gt;LOW RISK STATES:&lt;/text&gt;
  &lt;text x="120" y="320" font-size="11" fill="#333"&gt;Most Northeastern states, Midwest states with limited oil/gas activity&lt;/text&gt;
  &lt;text x="120" y="340" font-size="11" fill="#333"&gt;Note: Risk varies by county within states; local investigation essential&lt;/text&gt;
&lt;/svg&gt;
